begin;
create table app.import_batches (id uuid primary key default gen_random_uuid(),original_filename text not null,storage_object_key text,file_sha256 text not null check(file_sha256~'^[0-9a-f]{64}$'),file_size_bytes bigint not null check(file_size_bytes>0),template_version text,status app.import_status not null default 'UPLOADED',uploaded_by uuid references app.profiles(id),uploaded_at timestamptz not null default now(),validation_summary jsonb not null default '{}'::jsonb,confirmed_by uuid references app.profiles(id),confirmed_at timestamptz,failure_reason text,unique(file_sha256,template_version));
create table app.import_staging_records (id uuid primary key default gen_random_uuid(),import_batch_id uuid not null references app.import_batches(id) on delete cascade,row_number integer not null check(row_number>0),worksheet_name text,source_cell_range text,raw_payload jsonb not null,parsed_scope app.reporting_scope,parsed_period_code text,parsed_unit_code text,parsed_metric_code text,parsed_category_code text,parsed_amount numeric(20,2),parsed_budget_scope app.budget_scope,normalized_payload jsonb,availability app.availability_status not null default 'NOT_AVAILABLE',validation_status text not null default 'PENDING' check(validation_status in('PENDING','VALID','WARNING','ERROR')),duplicate_fingerprint text,unique(import_batch_id,row_number,worksheet_name,source_cell_range));
create table app.import_issues (id uuid primary key default gen_random_uuid(),import_batch_id uuid not null references app.import_batches(id) on delete cascade,staging_record_id uuid references app.import_staging_records(id) on delete cascade,severity app.issue_severity not null,code text not null,field_name text,message_th text not null,message_en text not null,details jsonb not null default '{}'::jsonb,resolved_at timestamptz,resolved_by uuid references app.profiles(id),resolution_note text);
create table app.import_commits (id uuid primary key default gen_random_uuid(),import_batch_id uuid not null references app.import_batches(id),staging_record_id uuid not null references app.import_staging_records(id),financial_record_id uuid not null references app.financial_records(id),committed_at timestamptz not null default now(),unique(import_batch_id,staging_record_id,financial_record_id));
commit;
